mapper.select:
select sa.*,sum(sp.seckill_stock) as productCount from seckill_activity sa
left join seckill_product sp
on sp.activity_id = sa.id

    and merchant_id = #{merchantId}

        and name like concat('%', #{pageQueryDTO.keyword}, '%')


    and status = #{pageQueryDTO.status}


    and deleted = #{pageQueryDTO.deleted}


group by sa.id
